PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE STREET_SWEEPER_INFO (
    VEHICLE_ID varchar,
    BLOWER_RUN varchar,
    SIDE_LEFT_BRUSH_RUN varchar,
    SIDE_RIGHT_BRUSH_RUN varchar,
    FRONT_BRUSH_RUN varchar,
    FLAP_RUN varchar,
    WATER_PUMP_RUNS varchar,
    REGIST_DATE varchar DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'::text)
);
CREATE TABLE VEHICLE_ING_INFO (
    I_INDEX int4 PRIMARY KEY AUTOINCREMENT,
    VEHICLE_ID varchar,
    VEHICLE_TYPE varchar,
    TTC varchar,
    ING_ACCELERAION varchar,
    HANDLE_ANGLE varchar,
    C_SEQ varchar,
    LATITUDE varchar,
    LONGITUDE varchar,
    C_TIMESTAMP varchar,
    INTER_VEHICLE_DISTANCE varchar,
    SPEED varchar,
    LATERAL_ACCELERATION varchar,
    WIPER_STATUS varchar,
    MDPS_ANGLE varchar,
    DRIVING_DISTANCE varchar,
    EMERGENCY_LIGHT varchar,
    WHEEL_SPEED varchar,
    AUTO_DRIVING_STATUS varchar,
    TRANSMISSION varchar,
    V_TIMESTAMP varchar DEFAULT  to_char(now(), 'YYYY-MM-DD HH24:MI:SS'::text),
    TURN_SIGNAL varchar,
    YAW_RATE varchar,
    BRAKING_STATUS varchar,
    BRAKING_TYPE varchar,
    SENSOR_TYPE varchar,
    S_TIMESTAMP varchar,
    SENSOR_STATUS varchar,
    SENSOR_ID varchar,
    GOAL_LONGITUDE varchar,
    J_SEQ varchar,
    MOTION_PLAN varchar,
    GOAL_SPEED varchar,
    TARGET_OBJ_SPEED varchar,
    TARGET_OBJ_PREDICT varchar,
    TARGET_OBJ varchar,
    GOAL_ACCELERATION varchar,
    TARGET_OBJ_DISTANCE varchar,
    J_TIMESTAMP varchar,
    GOAL_LATITUDE varchar,
    GOAL_WHEEL_ANGLE varchar,
    L_LATITUDE varchar,
    L_TIMESTAMP varchar,
    L_SPEED varchar,
    HEADING varchar,
    L_LONGITUDE varchar,
    LANE varchar,
    OBSTACLE_ARR varchar,
    TRAFFIC_LIGHT_ARR varchar,
    T_TIMESTAMP varchar,
    TRAFFIC_LIGHT_ID varchar,
    TRAFFIC_LIGHT varchar,
    OBSTACLE_WIDTH varchar,
    OBSTACLE_LNG_SPEED varchar,
    OBSTACLE_ID varchar,
    OBSTACLE_LATERAL_ABS_SPEED varchar,
    O_TIMESTAMP varchar,
    OBSTACLE_DISTANCE varchar,
    OBSTACLE_HEADING varchar,
    OBSTACLE_LATERAL_SPEED varchar,
    OBSTACLE_LNG_ABS_SPEED varchar,
    OBSTACLE_TYPE varchar,
    REGIST_DATE date,
    REAL_DIV varchar,
    ARRIVAL_NAME varchar,
    ARRIVAL_DISTANCE varchar,
    ARRIVAL_TIME varchar,
    ARRIVAL_ID varchar,
    GEAR_STATUS varchar,
    BRAKE_STATUS varchar,
    LOAD_CAPACITY varchar,
    BATTERY_REMAINING_CAPACITY varchar,
    BATTERY_VOLTAGE varchar,
    BATTERY_TEMPERATURE varchar,
    BRAKE varchar,
    BRAKE_TYPE varchar,
    ACCEL varchar,
    WORK_RATE varchar
);
CREATE TABLE IF NOT EXISTS "TRACTOR_INFO" (
    "VEHICLE_ID" varchar,
    "ENGINE_SPEED" REAL,
    "ACTUAL_ENGINE_PERCENT_TORQUE" REAL,
    "ENGINE_COOLANT_TEMPERATURE" REAL,
    "AMBIENT_AIR_TEMPERATURE" REAL,
    "ENGINE_EXHAUST_GAS_TEMPERATURE" REAL,
    "FUEL_LEVEL" REAL,
    "REPRESENTS_POSITIONOF_HITCH" REAL,
    "PTO_LAMP" INTEGER,
    "FWD_LAMP" INTEGER,
    "SHIFT_LAMP" INTEGER,
    "SHIFT_AUTO_LAMP" INTEGER,
    "KEYSWITCH_BATTERY_POTENTIAL" REAL,
    "GPS_SENSOR_STATUS" INTEGER,
    "NTRIP_STATUS" INTEGER,
    "DRAFT_SENSOR_STATUS" INTEGER,
    "HITCH_SENSOR_STATUS" INTEGER,
    "VEHICLE_SPEED_SENSOR_STATUS" INTEGER,
    "EMERGENCY_STOP" INTEGER,
    "REGIST_DATE" varchar DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'::text)
);
CREATE TABLE IF NOT EXISTS "WORK_INFO_TRACTOR" (
    "VEHICLE_ID" varchar,
    "WORK_AREA" varchar,  -- JSON 데이터는 SQLite에서 varchar로 저장
    "WORK_PATH" varchar,  -- JSON 데이터는 SQLite에서 varchar로 저장
    "REGIST_DATE" varchar DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'::text)
);
CREATE TABLE IF NOT EXISTS "VEHICLE_EVENT" (
    "VEHICLE_ID" varchar,
    "VEHICLE_TYPE" varchar,
    "EVENT_CODE" varchar,
    "EVENT_DESCRIPTION" varchar,
    "REGIST_DATE" varchar DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'::text)
);
CREATE TABLE IF NOT EXISTS "GLOBAL_PLAN_HISTORY" (
    "REQUEST_DATE" varchar,
    "REQUEST_AREA" varchar,  -- JSON 데이터는 SQLite에서 varchar로 저장
    "RESULT" varchar,        -- JSON 데이터는 SQLite에서 varchar로 저장
    "MISSION_PROGRESS" INTEGER,  -- PostgreSQL의 int4를 SQLite의 INTEGER로 변환
    "REGIST_DATE" varchar DEFAULT to_char(now(), 'YYYY-MM-DD HH24:MI:SS'::text)
);
DELETE FROM sqlite_sequence;
COMMIT;
